module examples.sum_to_n

export {
  fn main
}

fn main(n: U64) -> U64 {
  var i = 0
  var total = 0
  if n < 1001 {
    while i < n {
      i = i + 1
      let snapshot = i
      total = total + snapshot
    }
  } else {
    defect "input exceeds 1000"
  }
  total
}

