// whose published `Fails` values DISAGREE (`ErrA` vs `ErrB`), so
// joinFails' documented, disclosed non-order-independence (D-07-53 --
// the accumulator always wins over a later disagreeing value) is
// actually exercised, not merely a same-value no-op join. This fixture
// exists so a Go test can assert `main`'s published `Fails` is the SAME
// value whether read from `originvalidate.BuildInterface` (the producer)
// or `corevalidate.Validate`'s independently-derived peer signature --
// producer/peer parity for `Fails` under a genuinely disagreeing,
// order-sensitive join, not just the identity/equal-merge cases
// call_fallible_foreign_reach.lang already covers.
//
// This fixture checks and corevalidates clean; it is a witness about a
// published FIELD's value, not a refusal fixture.

module phase07.call_two_fallible_callees_disagree

export {
  fn main
}

foreign C {

  fn probe_a(request: Byte) -> Byte {
    unwind: forbidden
    nonlocal_exit: forbidden
    allocator: "libc_malloc"
    fails: ErrA
  }

  fn probe_b(request: Byte) -> Byte {
    unwind: forbidden
    nonlocal_exit: forbidden
    allocator: "libc_malloc"
    fails: ErrB
  }
}

data ErrA =
  | ErrAFailed

data ErrB =
  | ErrBFailed

fn tracer_a(value: Byte) -> Byte {
  let result = try probe_a(value)
  result
}

fn tracer_b(value: Byte) -> Byte {
  let result = try probe_b(value)
  result
}

fn main(value: Byte) -> Byte {
  let first = tracer_a(value)
  let second = tracer_b(first)
  second
}

// 07-09: the standing negative control for 07-VERIFICATION.md's single
// FAILED must-have truth and 07-REVIEW.md's CR-01 (CRITICAL/BLOCKER).
// Before this plan, this program was admitted with `status: pass` and
// zero diagnostics: `check.resolveCallBinding` copied the CALLER's own
// argument TypeID into the OpCall target and never consulted the
// callee's declared parameter type, so a `Buffer` argument was silently
// accepted by a callee declared to take a `Byte`.
//
// The refusal this fixture proves is a TYPE CONTRACT refusal, not a
// callability refusal (`identity` is perfectly callable -- it is
// exported-safe and carries no borrowed return) and not a cycle refusal
// (the call graph `main -> identity` is acyclic). This fixture must
// never be added to any list that expects a clean check, in the same
// way `cycle_self.lang` never is.

module phase07.call_type_mismatch

export {
  fn main
}

fn identity(value: Byte) -> Byte {
  value
}

fn main(buffer: Buffer) -> Buffer {
  let result = identity(buffer)
  result
}

// SEM-06's negative control (D-07-34): `main` calls `relay`, whose body is
// the identical shape to testdata/phase07/clean_but_unpublishable.lang's own
// `relay` -- it checks clean on its own (zero diagnostics from
// session.Check), but fails publication with core.origin_omitted, so
// originvalidate.PublishProblemsFor reports Callable == false for it. The
// call is refused because `relay` is NOT PUBLISHABLE -- a publication-safety
// failure (D-04-03, D-07-31, D-07-32) -- NOT because it is unexported. An
// unexported-callee fixture would be the WRONG negative control here: it
// would test a rule D-04-03 never stated (D-07-31b). `relay` is declared
// exported below specifically to make that distinction unmistakable: this
// refusal fires with export membership held constant.
//
// A cross-module copy of this callee already exists as
// testdata/phase07/clean_but_unpublishable.lang; it is repeated here (module
// line and caller aside) because calls in this phase resolve only within a
// single parsed program (D-07-01) -- there is no cross-module call channel
// yet for `main` to reach that file's `relay` directly.

module phase07.call_uncallable_callee

export {
  fn relay
  fn main
}

fn relay(buffer: Buffer) -> Buffer {
  let view = borrow mut buffer
  let reviewed = borrow view
  view
}

fn main(buffer: Buffer) -> Buffer {
  let result = relay(buffer)
  result
}

// This fixture checks clean (zero diagnostics from session.Check) but
// fails publication with core.origin_omitted, so BuildInterface reports
// Callable == false for fn relay. It is the correct negative control for
// SEM-06 BECAUSE it trips the publication-safety predicate
// (originvalidate.PublishProblemsFor / ValidatePublished) rather than an
// export list -- Callable is publication safety, not export membership
// (D-04-03, D-07-31, D-07-32). An unexported callee would be the WRONG
// negative control for this predicate.
//
// Extracted verbatim (module line only changed) from
// internal/compiler/check/check_exclusive_test.go:46-58, where it is also
// embedded inline as the "clean" variant of
// TestExclusiveBorrowLowersToCore, and asserted again in
// internal/compiler/originvalidate/originvalidate_test.go's
// TestExclusiveBorrowCleanShapeChecksButCannotPublish. Amendment A-03
// claimed this witness did not exist; A-03 checked testdata/ for a file and
// reported the wrong conclusion -- D-07-44 corrects it.
//
// The pre-existing `fn relay` in testdata/phase3/shared_shared_accept.lang
// (module owned.shared_shared_accept) is a DIFFERENT fixture: an owned
// take/return that publishes with no problems at all. Do not confuse the
// two.

module phase07.clean_but_unpublishable

export {
  fn relay
}

fn relay(buffer: Buffer) -> Buffer {
  let view = borrow mut buffer
  let reviewed = borrow view
  view
}

