// SEM-07: a call graph whose calls form a cycle is refused with a named
// refusal code, never a hang. This is the length-3 case (A -> B -> C -> A),
// completing SEM-07's self (1, cycle_self.lang) / mutual (2,
// cycle_mutual.lang) / indirect (>= 3, this fixture) trio, distinguished
// by cycle_length and membership rather than by three separate codes.

module phase07.cycle_indirect

export {
  fn a
}

fn a(value: Byte) -> Byte {
  let result = b(value)
  result
}

fn b(value: Byte) -> Byte {
  let result = c(value)
  result
}

fn c(value: Byte) -> Byte {
  let result = a(value)
  result
}

// SEM-07 (D-07-17/D-07-18): a call graph whose calls form a cycle is
// refused with a named refusal code, never a hang -- never a native-
// recursion stack overflow. Fixtures are named by cycle length: this one
// is length 2 (mutual recursion). cycle_self (length 1) and cycle_indirect
// (length >= 3, landing in 07-07) are the only other names; there is no
// cycle_direct.lang, the superseded name.

module phase07.cycle_mutual

export {
  fn a
}

fn b(value: Byte) -> Byte {
  let result = a(value)
  result
}

fn a(value: Byte) -> Byte {
  let result = b(value)
  result
}

// SEM-07 (D-07-17/D-07-18): a call graph whose calls form a cycle is
// refused with a named refusal code. This fixture is the length-1 case:
// a function that calls itself directly. Skipping edges where
// callee == caller is a plausible-looking "optimization" that would
// silently legalize direct recursion -- it needs its own fixture and its
// own seeded mutation (Task 3, control:callgraph.self_edge). Fixtures are
// named by cycle length: cycle_mutual (length 2, 07-06 Task 1) and
// cycle_indirect (length >= 3, landing in 07-07) are the only other
// names; there is no cycle_direct.lang.

module phase07.cycle_self

export {
  fn loop_forever
}

fn loop_forever(value: Byte) -> Byte {
  let result = loop_forever(value)
  result
}

// D-07-28: a cycle whose CLOSING edge originates INSIDE a match arm.
// call_from_both_match_arms.lang (07-04) proved enumerate-by-kind-across-
// all-blocks on the ADMISSION path; this fixture proves the same property
// on the REFUSAL path -- the Phase-12 blindness guard made real without
// `Result` payloads. `main` and `helper` are both arm-bodied match
// functions (a module cannot mix a match-bodied function with a
// straight-line one -- core.mixed_body_versions).

module phase07.cycle_through_match_arm

export {
  fn main
}

data Choice =
  | A
  | B

fn helper(value: Choice) -> Choice {
  match value {
    A => {
      let result = main(value)
      result
    }
    B => {
      value
    }
  }
}

fn main(flag: Choice) -> Choice {
  match flag {
    A => {
      let result = helper(flag)
      result
    }
    B => {
      flag
    }
  }
}

