// Phase 07's rules alone. `check`'s intraprocedural loan-liveness law
// (computeLoanLastUses) builds its shadow use-chain from each binding's
// RHS.Source; a "call" binding carries RHS.Arguments, not RHS.Source, so
// the call at `let aliased = relay(borrowed)` was invisible to that chain
// as a use of `borrowed` -- the exclusive loan on `buffer` was treated as
// ending at its own creation point, with no visible use surviving into or
// past the call, and `take buffer` on the next line was admitted even
// though `aliased` (the call's own return, standing in for the borrowed
// view `relay` actually returns) remained live afterward. This was the
// INTERPROCEDURAL half of D-03-02.
//
// CLOSED in Phase 08: `derivePlaceLoans`'s forward canonicalization pass
// (D-08-07) now consults `relay`'s declared return contract
// (`-> borrow mut(buffer) Buffer`, Mode == "exclusive") via the in-memory
// interprocedural summary table, and propagates `buffer`'s loan across the
// OpCall boundary onto `aliased`. `take buffer` is now refused with
// `check.interprocedural_loan_liveness`, asserted explicitly by
// `TestRelayEscortWitnessRefusesInterproceduralLiveness` (check_test.go),
// which replaces the retired
// `TestRelayEscortWitnessChecksCleanPendingInterproceduralLiveness`.
//
// The pre-existing `fn relay` in testdata/phase3/shared_shared_accept.lang
// (module owned.shared_shared_accept) is a DIFFERENT fixture: an owned
// take/return with two overlapping SHARED loans, no exclusive borrow, no
// dangling-alias shape, and it publishes with no problems at all. Do not
// confuse the two.

module phase07.relay_escort_witness

export {
  fn escort
}

fn relay(buffer: Buffer) -> borrow mut(buffer) Buffer {
  let view = borrow mut buffer
  view
}

fn escort(buffer: Buffer) -> borrow mut(buffer) Buffer {
  let borrowed = borrow mut buffer
  let aliased = relay(borrowed)
  let delivered = take buffer
  aliased
}

