// Phase 08 Task 2(a) -- composition depth >= 2 (D-08-28.2), REFUSING member.
// Twin of relay_depth2_accept.lang. Three functions, caller -> relay -> leaf:
// leaf declares a shared-borrow return of its own parameter
// (`-> borrow(buffer) Buffer`); relay locally borrows ITS OWN parameter
// first, then forwards that borrow to leaf and returns leaf's result
// (`-> borrow(buffer) Buffer` too, satisfying originvalidate's own
// origin-recomputation walk, which is transparent through an OpCall and
// needs a LOCAL borrow hop somewhere in the causal chain back to relay's own
// parameter -- forwarding the bare parameter directly, without relay's own
// local borrow, makes relay unpublishable/uncallable, core.origin_understated,
// a wholly separate, pre-existing gate this fixture must route around, not a
// Phase 08 concern); caller runs the exact Pattern A shape (twin_a_refuse.lang)
// against relay, not leaf.
//
// A depth-1-only corpus cannot distinguish "the derivation genuinely reads a
// callee's declared signature" from "it happens to work for the one-hop
// case" -- this is the direct generalization of Phase 07's own finding that
// a straight chain could not kill the highest-value cycle mutation and
// diamonds were required (07-06-SUMMARY.md). Expected: `check` refuses with
// check.interprocedural_loan_liveness, and the emitted cause 2
// (loan_extended_by_call) names RELAY's own function ID -- not leaf's --
// proving the caller's admission consulted relay's OWN interprocedural
// summary entry (built from relay's own declared core.FunctionSignature),
// never reaching into leaf's signature or body at all.

module phase08.relay_depth2_refuse

export {
  fn caller
}

fn leaf(buffer: Buffer) -> borrow(buffer) Buffer {
  let observed = borrow buffer
  observed
}

fn relay(buffer: Buffer) -> borrow(buffer) Buffer {
  let borrowed = borrow buffer
  let forwarded = leaf(borrowed)
  forwarded
}

fn caller(buffer: Buffer) -> borrow(buffer) Buffer {
  let borrowed = borrow buffer
  let aliased = relay(borrowed)
  let delivered = take buffer
  aliased
}

// Phase 08 Task 1 -- Pattern A (ReturnsBorrowOfParam), ACCEPTING member.
// Twin of twin_a_refuse.lang: escort's own body is byte-identical to the
// refusing member (verified by TestInterproceduralTwinPairsDifferOnlyInTheCallee).
// The ONE thing that differs is escortee's DECLARED return type: here,
// `-> Buffer` (an ordinary owned return, body `let taken = take buffer;
// taken`), giving `core.FunctionSignature.Return.Mode == "owned"` and
// `returnsBorrowOfParam == false` in the interprocedural summary table --
// derivePlaceLoans' OpCall branch therefore does NOT propagate buffer's loan
// across the call boundary onto `aliased`, and `check.Program` (package
// check alone) admits this program with zero diagnostics: the refusal above
// is contract-driven, not shape-driven (must_haves backstop truth), proven by
// TestInterproceduralLivenessTwinPatternA against this exact fixture pair.
//
// KNOWN RESIDUAL (recorded in 08-03-SUMMARY.md's Deviations, NOT fixed here
// -- out of this plan's file scope and Phase 09's own charter, D-03-02's
// interprocedural peer half): running this fixture through the full `lang
// check` CLI additionally consults corevalidate.Validate as a peer once
// `check` itself passes (session.CheckCommandFile's fixed precedence,
// 07-10). corevalidate's own loan-liveness re-derivation
// (loanChainIndex.carriedLoans) sets `parent[operation.TargetID] =
// operation.SourceID` for EVERY operation kind, including OpCall -- so
// `aliased` (the call's own target) is treated as carrying buffer's loan
// forever, regardless of what escortee's own declared contract says.
// corevalidate therefore ALSO refuses this fixture (core.move_while_borrowed),
// even though `check`'s own interprocedural law -- the one Phase 08 builds --
// correctly admits it. This is corevalidate's still-intraprocedural
// summary-blindness (unmodified this phase, explicitly Phase 09's charter:
// "peer re-derivation and D-03-02 closure"), not a defect in this fixture or
// in the interprocedural law under test.

module phase08.twin_a_accept

export {
  fn escort
}

fn escortee(buffer: Buffer) -> Buffer {
  let taken = take buffer
  taken
}

fn escort(buffer: Buffer) -> Buffer {
