// Phase 12 Plan 03, Task 1 (D-12-15's third named refusal): the sole
// difference from testdata/phase12/payload_tracer.schway is the FIRST arm's
// construction binder -- `Ok(v) => Ok(w)` instead of `Ok(v) => Ok(v)`.
//
// D-12-14 provides exactly one shared payload place per arm this phase:
// the constructed argument and the pattern's own destructuring binder are
// the same declared place. Naming it "v" on the pattern side and "w" on
// the construction side asks for TWO distinct places where only one
// exists -- refused as check.payload_arity_mismatch, not silently resolved
// by picking one name over the other (which is what Plan 02's original
// parser shape would have done).

module result.payload_arity_mismatch

export {
  type Fault
  type Outcome
  fn identity
}

data Fault =
  | Broken

data Outcome =
  | Ok(Buffer)
  | Err(Fault)

fn identity(result: Outcome) -> Outcome {
  match result {
    Ok(v) => Ok(w)
    Err(e) => Err(e)
  }
}

// Phase 12 Plan 03, Task 1 (D-12-15's second named refusal): differs from
// testdata/phase12/payload_tracer.schway by replacing the second alternative
// (`Err(Fault)`, payload-carrying) with a genuinely nullary alternative,
// `Nope`, and matching it with a pattern binder it has no payload to fill --
// `Nope(x) => Nope` instead of a bare `Nope => Nope`.
//
// Nothing in this data type declares a payload for `Nope`
// (`AlternativeDetail.PayloadType == ""`), so a binder on its pattern is
// refused as check.binder_on_nullary_alternative -- the arm is trying to
// destructure a payload that was never declared.

module result.payload_binder_on_nullary

export {
  type Outcome
  fn identity
}

data Outcome =
  | Ok(Buffer)
  | Nope

fn identity(result: Outcome) -> Outcome {
  match result {
    Ok(v) => Ok(v)
    Nope(x) => Nope
  }
}

// Phase 12 Plan 03, Task 3 -- the anti-Pitfall-1 fixture (12-RESEARCH.md's
// Common Pitfalls, Pitfall 1: vacuous exhaustive-dispatch coverage).
//
// Architectural finding, recorded rather than silently worked around
// (D-09-45's stale-reference/finding discipline, applied here to a
// GRAMMAR limit rather than a stale doc): a payload destructure/
// construct pair is ONLY emitted for a BARE-VALUE match arm
// (analyzePayloadArm, D-12-05) -- a bare arm has no braces, so there is
// no linear body inside it in which a `let x = borrow ...` statement
// could ever appear. A BODY arm (`Pattern => { ... }`) CAN contain a
// real borrow sequence (analyzeArmBody, exactly `choose` below), but
// analyzeArmBody does not consult a payload binder at all -- and
// `core.mixed_arm_forms` forbids mixing bare-value and body arms in one
// match regardless. So a payload destructure and an explicit borrow
// statement CANNOT be combined inside the SAME match function this
// phase without extending analyzeArmBody itself (out of this plan's
// declared file scope -- check.go is not in Task 3's file list).
//
// The achievable, still-genuine combination: two functions, ONE program,
// checked and validated together in a single check.Program /
// corevalidate.Validate pass. `choose` is `testdata/phase3/
// branch_one_arm_shared_accept.schway`'s own function, UNCHANGED --  a real
// shared borrow whose last use precedes a sibling arm's plain move,
// driven through checkBranch's loanLivenessFixpoint. `identity` is the
// payload tracer's own function, UNCHANGED -- both new operation kinds,
// driven through the SAME six-site control. Per D-12-32/mixed_body_
// versions, a program may not mix Match-bodied and Linear-bodied
// FUNCTIONS, but both of these are Match-bodied (checkBranch handles
// bare-value and body arms alike), so they coexist in one module without
// tripping that guard -- this is what stops the exhaustive-dispatch
// control from reporting coverage of "payload operations meeting borrow
// machinery" that a construct-then-match-only corpus would not actually
// have earned.

module result.payload_borrow_interaction

export {
  type Switch
  type Fault
  type Outcome
  fn choose
  fn identity
}

data Switch =
  | On
  | Off

data Fault =
  | Broken

data Outcome =
  | Ok(Buffer)
  | Err(Fault)

fn choose(flag: Switch) -> Switch {
  match flag {
    On => {
      let view = borrow flag
      let noted = view
      let moved = take flag
      moved
    }
    Off => {
      let held = take flag
      held
    }
  }
}

fn identity(result: Outcome) -> Outcome {
  match result {
    Ok(v) => Ok(v)
    Err(e) => Err(e)
  }
}

// Phase 12 Plan 03, Task 3 (D-12-29): criterion 1's own witness for the
// affine drop obligation.
//
// D-12-29's precise meaning, stated here so the criterion's own wording is
// never misread as implying a destructor count that does not exist: with
// NO core.OpDrop in AllOperationKinds() and "drop" being the TYPE-LEVEL
// ability core.AbilityDrop, "dropped exactly once" is NOT a countable
// runtime event. It is a STATIC by-function-end accounting property that
// check's worklist and corevalidate's set-propagation each derive
// INDEPENDENTLY, for EVERY alternative -- including whichever ones are
// NOT taken on a given run (a sum type executes exactly one arm; the
// "unmoved" alternatives' own payload obligations are still proven
// statically, never executed).
//
// `Ok` and `Err` each independently bind their own payload and consume it
// (destructure then reconstruct, D-12-14's single shared place, moved out
// and moved back in exactly once). `Nope` is genuinely nullary -- nothing
// to bind, nothing to move, the scrutinee alias returned untouched.
// TestPayloadDropObligation asserts the checked program contains exactly
// two destructure_payload operations (one per payload-carrying
// alternative, zero for `Nope`) -- proving a lowering that silently
// skipped either payload arm's own obligation would be caught, which an
// interp-only run (exactly one arm per invocation) cannot catch on its
// own.

module result.payload_drop_obligation

export {
  type Fault
  type Outcome
  fn identity
}

data Fault =
  | Broken

data Outcome =
  | Ok(Buffer)
  | Err(Fault)
  | Nope

fn identity(result: Outcome) -> Outcome {
  match result {
    Ok(v) => Ok(v)
    Err(e) => Err(e)
    Nope => Nope
  }
}

