// Phase 12 Plan 06, Task 1 (CR-01 / D-12-44): the sole difference from
// testdata/phase12/payload_tracer.schway is that BOTH alternatives of
// `Outcome` carry the SAME payload type, `Buffer`, instead of one `Buffer`
// and one `Fault`. The second alternative keeps a distinct NAME (`Failed`,
// not `Err`) -- `core.NewDataType` already refuses duplicate ALTERNATIVE
// NAMES, and this fixture exists to provoke the NEW refusal this plan adds,
// not that pre-existing one.
//
// Refused at DECLARATION time, before any function body is checked:
// `check.duplicate_payload_type`. Both `cgen.alternativeNameForPayloadType`
// and `interp.alternativeNameForPayloadType` resolve an operation's
// declaring alternative from `PayloadType` alone via first-match linear
// scan -- with two alternatives sharing one payload type, that resolution
// is genuinely ambiguous, and because both engines independently
// reimplemented the SAME flawed derivation, the phase's own three-engine
// convergence tests are structurally incapable of catching it. A CLEAN
// check result on this fixture is a control failure.

module result.payload_duplicate_payload_type

export {
  type Outcome
  fn identity
}

data Outcome =
  | Ok(Buffer)
  | Failed(Buffer)

fn identity(result: Outcome) -> Outcome {
  match result {
    Ok(v) => Ok(v)
    Failed(e) => Failed(e)
  }
}

// Phase 12 Plan 03, Task 1 (D-12-15's first named refusal): differs from
// testdata/phase12/payload_tracer.schway by adding a third, genuinely
// nullary alternative (`Nope`) and matching the payload-carrying `Ok`
// alternative with NEITHER a pattern binder nor a construction binder --
// `Ok => Nope` instead of `Ok(v) => Ok(v)`.
//
// Because neither side names a place, check.go's fallback (pattern binder,
// else construction binder) resolves to the empty string, and `Ok`
// declares a payload (Buffer) that has nowhere to go: refused as
// check.missing_payload_binder. The other two arms are ordinary and
// contribute no diagnostics, so the refusal is attributable to this one
// arm alone.

module result.payload_missing_binder

export {
  type Fault
  type Outcome
  fn identity
}

data Fault =
  | Broken

data Outcome =
  | Ok(Buffer)
  | Err(Fault)
  | Nope

fn identity(result: Outcome) -> Outcome {
  match result {
    Ok => Nope
    Err(e) => Err(e)
    Nope => Nope
  }
}

// Phase 12 Plan 03, Task 2 (D-12-27's fail-closed resource-payload
// refusal): `Handle`'s only alternative, `Held(Byte)`, names the exact
// type (`Byte`) the declared foreign symbol `schway_res_open` returns --
// this project's only channel for a Phase-4 tracked, release-obligated
// value (checkResourceLifecycle/checkForeignTracer track a foreign
// acquisition by VALUE PROVENANCE, never by a distinguishing type shape,
// so a payload type NAMING a declared foreign return type is the
// structurally-derivable signal this refusal is built on -- deliberately
// over-inclusive, fail-closed and conservative, per D-12-28's own
// precedent for the sibling D-10-C01 refusal).
//
// Refused at DECLARATION time, before any function body is even checked:
// `check.resource_payload_refused`. The full resource-in-payload rule
// lands only when all three of D-10-C01, D-10-C02, and D-10-C04 are
// resolved (PHASE-12-DEBT.md's D-12-30 landing condition) -- none of
// which is Phase 12's to close.

module result.payload_resource_refused

export {
  fn main
}

foreign C {

  fn schway_res_open(request: Byte) -> Byte {
    unwind: forbidden
