// A reborrow keeps the original loan live: loan liveness is transitive.

module owned.reborrow_while_moved

export {
  fn relay
}

fn relay(code: Byte) -> Byte {
  let view = borrow code
  let review = borrow view
  let delivered = take code
  let observed = review
  delivered
}

module owned.use_after_move

export {
  fn relay
}

fn relay(buffer: Buffer) -> Buffer {
  let delivered = take buffer
  let duplicate = take buffer
  delivered
}

module phase23.discard_owner

export {
  fn main
}

foreign C {
  fn schway_file_byte_acquire(path: PathToken) -> FileByteOwner {
    unwind: forbidden
    nonlocal_exit: forbidden
    mode: "acquire"
    abi: schway_file_byte_acquire_fn
    allocator: "libc_malloc"
    release: "schway_file_byte_release"
    fails: AcquireError
  }

  fn schway_file_byte_use(owner: FileByteOwner) -> U64 {
    unwind: forbidden
    nonlocal_exit: forbidden
    mode: "borrow"
    abi: schway_file_byte_use_fn
    fails: UseError
  }

  fn schway_file_byte_release(owner: FileByteOwner) -> Unit {
    unwind: forbidden
    nonlocal_exit: forbidden
    mode: "consume"
    abi: schway_file_byte_release_fn
    allocator: "libc_malloc"
  }
}

data AcquireError =
  | AcquireFailed

data UseError =
  | UnsupportedByte

fn main(path: PathToken) -> U64 {
  discard schway_file_byte_acquire(path) because "discarded owner"
  path
}

module phase25.exclusive_conflict_reject

export {
  fn relay
}

fn relay(value: Buffer) -> Buffer {
  let shared = borrow value
  let exclusive = borrow mut value
  let observed = take shared
  exclusive
}

module phase25.exclusive_copy_accept

export {
  fn exclusive_copy
}

fn exclusive_copy(value: U64) -> U64 {
  let borrowed = borrow mut value
  let copied = borrowed
  copied
}

