// Two overlapping exclusive loans on one owner conflict: two loans would
// both promise sole access.

module owned.exclusive_exclusive_reject

export {
  fn relay
}

fn relay(buffer: Buffer) -> Buffer {
  let first = borrow mut buffer
  let second = borrow mut buffer
  let observed = take first
  second
}

// A move of an owner while an exclusive loan is live is rejected exactly
// like the existing shared-loan rule, mirroring move_while_borrowed.lang.

module owned.exclusive_move_reject

export {
  fn relay
}

fn relay(buffer: Buffer) -> Buffer {
  let view = borrow mut buffer
  let delivered = take buffer
  let observed = take view
  delivered
}

// A public borrowed view declares its origin and access mode in the return
// type; the checker records a PublicOrigin fact independent of the body.

module owned.public_view

export {
  fn view
}

fn view(buffer: Buffer) -> borrow(buffer) Buffer {
  let observed = borrow buffer
  observed
}

