module owned.phase5_explain_use_after_move

export {
  fn relay
}

fn relay(buffer: Buffer) -> Buffer {
  let delivered = take buffer
  let duplicate = take buffer
  delivered
}

// adversarial-target: false-no-alias-hoist
//
// D-05-05's engineered false-alias control target. `value`'s SHARED (never
// exclusive) borrow chain covers the whole call: deriveAliasFacts (check.go)
// requires an EXCLUSIVE first borrow, so this fixture yields ZERO alias
// facts, and cgen's selectsByPointerLowering (also exclusive-first-gated)
// never selects it either -- production cgen instead selects the sibling
// selectsByPointerLoweringSharedOnly path (emitLinearBorrowedByPointerPlain),
// which lowers this parameter by pointer WITHOUT restrict (a shared loan
// alone never justifies it) and exposes a second, purely-adversarial raw
// pointer parameter (lang_alias_probe) that the unmutated body never reads
// or writes. session.AliasFactMutationRunner is the only thing that ever
// touches that dormant parameter: it injects a FALSE restrict onto the
// primary parameter and rewrites the body to demonstrate the resulting
// observable -O3 hoist, proving control:alias.false_no_alias has a real,
// engineered subject rather than an unexercised name (D-05-38).
module phase5.false_restrict_hoist

export {
  fn touch
}

fn touch(value: Byte) -> Byte {
  let first = borrow value
  first
}

// adversarial-target: inline-across-foreign-call
//
// D-05-18a: a single foreign acquisition whose result FEEDS the function's
// own return value (an observable), the shape under which `-flto` legally
// lets Clang inline lang_foreign_resource.c's tiny `_LANG_lang_res_open`
// body directly at this call site -- the separately-compiled TU is opaque
// to the optimizer without LTO, so this is exactly the case D-05-24 names
// as necessary for a real (not green-by-construction) `-O3`/LTO
// differential. Structurally identical to testdata/phase4/foreign_acquire_one.lang
// (this phase's peer, not a fork of it -- a new file per D-05-18).

module phase5.inline_across_foreign

export {
  fn main
}

foreign C {

  fn lang_res_open(request: Byte) -> Byte {
    unwind: forbidden
    nonlocal_exit: forbidden
    allocator: "libc_malloc"
    fails: AcquireError
  }
}

data AcquireError =
  | OpenFailed

fn main(request: Byte) -> Byte {
  let handle = try lang_res_open(request)
  handle
}

// adversarial-target: reordering-of-two-independent-event-emissions
//
// D-05-18a: two successive foreign acquisitions, A then B, with no data
// dependence between them -- neither's acquired value feeds the other, and
// both are dropped unread, the function returning its own untouched
// parameter. Because A and B are mutually independent, a reordering
// optimizer is legally free to swap their emitted events (and, under
// `-flto`, their real call order) while producing the identical terminal
// value -- exactly the shape D-05-20's compared "semantic-event order with
// causal identity" axis exists to catch, since a real reorder would produce
// a different ordered event sequence even though the terminal outcome is
// unchanged.

module phase5.reorder_two_events

export {
  fn main
}

foreign C {

  fn lang_res_open(request: Byte) -> Byte {
    unwind: forbidden
    nonlocal_exit: forbidden
    allocator: "libc_malloc"
    fails: AcquireError
  }
}

data AcquireError =
  | OpenFailed

fn main(request: Byte) -> Byte {
  let a = try lang_res_open(request)
  let b = try lang_res_open(request)
  request
}

// D-05-02 tracer fixture: touch's sole Buffer parameter is exclusively
// borrowed as the very FIRST use in the body (`borrow mut buffer`) and never
// referenced again directly -- every remaining operation is a reborrow
// chained off that exclusive loan (a repeated load/store over the borrowed
// view an optimizer could hoist, the seed of D-05-05's later engineered
// fixture), so the loan's own last use is the function's own terminator.
// This is the structural shape selectsByPointerLowering (cgen.go) detects:
// exclusive loan on the parameter covering every operation from the
// parameter's first use to the terminator, never a fixture-name allowlist.
//
// The return type is a PLAIN owned `-> Buffer`, not a declared
// `borrow(...)` view: selectsByPointerLowering additionally requires
// function.PublicOrigin == nil, so a declared borrow-return function (e.g.
// testdata/phase3/public_view_mixed_access.lang, which has the identical
// exclusive-borrow-then-reborrow-to-terminator operation shape) never
// selects this path -- PublicOrigin is a genuinely distinct, already-shipped
// semantic category this plan does not touch. check.go admits a plain
// return of a borrow-derived place unchanged (no checker change this plan;
// this is the documented D-03-02 gap, not a new behavior).
module phase5.restrict_borrow

export {
  fn touch
}

fn touch(buffer: Buffer) -> Buffer {
  let first = borrow mut buffer
  let second = borrow first
  let third = borrow second
  third
}

// adversarial-target: retained-pointer-use-after-free
//
// D-05-06/D-05-09: a real allocate / use / free / use-again cycle across
// three successive calls to the SAME declared symbol -- the identical
// call-count convention native/lang_foreign_nonlocal.c already establishes
// for a shared-symbol foreign shape (D-04-17/D-04-18), reused here because
// core.Function/cgen carry exactly one ForeignContract per function, so a
// resource-lifecycle sequence always calls its FIRST declared symbol for
// every step (verified empirically while authoring this fixture). The
// first call (native/lang_foreign_retained.c's `lang_retained_open`
// helper) genuinely allocates a one-byte buffer and stashes its pointer in
// `static` storage -- FFI-003's retained-pointer lifetime shape, needing
// no calls-into-Lang (M001 has none by design). The second call reads it
// back while still live. The third call (`lang_retained_stale`) frees the
